package com.bank.scratchpool;

import java.sql.Connection;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.logging.Logger;

// A minimal pool: bounded BlockingQueue of pre-opened connections.
public class SimpleConnectionPool {
    private static final Logger log = Logger.getLogger(SimpleConnectionPool.class.getName());
    private final BlockingQueue<Connection> idle;
    private final int size;

    public SimpleConnectionPool(ConnectionFactory factory, int size) throws Exception {
        this.size = size;
        this.idle = new ArrayBlockingQueue<>(size);  // bounded = hard cap
        for (int i = 0; i < size; i++) {
            idle.offer(factory.open());               // pre-open all connections
        }
        log.info(() -> "Pool created with " + size + " connections");
    }

    // Borrow: blocks up to timeout, then fails fast (like connectionTimeout).
    public Connection borrow(long timeoutMs) throws InterruptedException {
        Connection c = idle.poll(timeoutMs, TimeUnit.MILLISECONDS);
        if (c == null) throw new IllegalStateException("Pool exhausted — no connection in " + timeoutMs + "ms");
        log.fine(() -> "Borrowed; idle now " + idle.size());
        return c;
    }

    // Release: offer returns the connection for the next waiter. close() does NOT destroy.
    public void release(Connection c) {
        idle.offer(c);
        log.fine(() -> "Released; idle now " + idle.size());
    }

    public int capacity() { return size; }
    public int available() { return idle.size(); }

    // Functional factory so the demo can plug in a fake or a real connection.
    public interface ConnectionFactory { Connection open() throws Exception; }
}
