package com.bank.scratchpool;

import java.sql.Connection;
import java.util.logging.Logger;

public class PooledWork {
    private static final Logger log = Logger.getLogger(PooledWork.class.getName());
    private final SimpleConnectionPool pool;

    public PooledWork(SimpleConnectionPool pool) { this.pool = pool; }

    public void checkBalance(String accountId) {
        Connection conn = null;
        try {
            conn = pool.borrow(3000);  // wait max 3s
            log.info(() -> "Checked balance for " + accountId + " using pooled connection");
            // ... run the query here ...
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            if (conn != null) pool.release(conn);  // ALWAYS return — forgetting this leaks
        }
    }
}
