package com.bank.scratchpool;

import java.sql.Connection;
import java.util.logging.Logger;

public class ScratchPoolDemo {
    private static final Logger log = Logger.getLogger(ScratchPoolDemo.class.getName());

    public static void main(String[] args) throws Exception {
        // Fake connections so the demo runs without a real database.
        SimpleConnectionPool pool = new SimpleConnectionPool(
            () -> (Connection) java.lang.reflect.Proxy.newProxyInstance(
                Connection.class.getClassLoader(),
                new Class[]{Connection.class},
                (p, m, a) -> m.getName().equals("toString") ? "fakeConn" : null),
            2);  // only 2 connections to show blocking

        PooledWork work = new PooledWork(pool);
        work.checkBalance("SAV2001");
        work.checkBalance("CUR3001");
        log.info(() -> "Available after returns: " + pool.available() + "/" + pool.capacity());

        // Show the cap: borrow both, then a 3rd borrow would block then time out.
        Connection a = pool.borrow(3000);
        Connection b = pool.borrow(3000);
        try {
            pool.borrow(500);  // pool empty → blocks 500ms → fails fast
        } catch (IllegalStateException e) {
            log.severe("Expected exhaustion: " + e.getMessage());
        } finally {
            pool.release(a);
            pool.release(b);
        }
        log.info("HikariCP improves this with a lock-free ConcurrentBag, validation, maxLifetime, and leak detection.");
    }
}
